  insert into public.class_lesson_content (session_id, event_type, status, blocks, updated_at)
    values ('949f1d47-1a70-423d-8f7b-7fdf86c233fd', 'lesson', 'published', $j$[{"kind": "recap", "title": "Từ Buổi 06 – 07 sang Buổi 08", "steps": [{"label": "Melody", "items": ["Đọc nốt, chọn vùng đàn, xếp ngón tay trái (Buổi 01–04).", "Nốt ♯/♭ tìm từ nốt đã biết (Buổi 04)."]}, {"label": "Bass", "items": ["Chọn bass theo tên hợp âm: gốc hoặc quãng 5 (Buổi 02, 05).", "Nối nốt bằng gảy lại · trượt · luyến (Buổi 03, 05)."]}, {"label": "Chord / lót", "items": ["Thêm lót vào chỗ giai điệu ngân dài (Buổi 06).", "Buổi 07 bạn đã thực hành trên bài mẫu."]}], "message": "Buổi 08 không dạy kỹ thuật mới. Hôm nay bạn tự làm trọn một bản Solo Guitar trình độ 1 từ một tờ phôi."}, {"kind": "objectives", "title": "Cuối buổi, bạn làm được", "items": ["Nói được quy trình ba bè: Melody → Bass → Chord, và vì sao xếp ngón không tách rời.", "Tự chuyển soạn một bản nhạc phôi trên giấy theo ba bước.", "Đàn lần lượt Melody, Melody + Bass, rồi cả ba bè; sửa lại bản giấy cho khớp với bài đàn.", "⭐ QUAN TRỌNG NHẤT — Đạt ĐÚNG ở cả ba bè là đạt chuẩn tốt nghiệp Chặng 1. ĐẸP và ĐỘC ĐÁO là mức phát triển, không bắt buộc."]}, {"kind": "note", "title": "Nhịp 1 · Tổng kết quy trình", "text": "Một bản Solo Guitar là ba bè chồng lên nhau: Melody là bông hoa, Bass là cột nhà, Chord là lớp lót giữa hai bè. Thứ tự làm luôn là Melody trước, rồi Bass, rồi Chord. Mỗi lần thêm một bè, hãy quay lại xem bè trước còn đàn được không. Nếu không, sửa cách xếp ngón hoặc bỏ bớt phần phụ — Melody và Bass là phần không được mất. Kết thúc nhịp: Bài trả 8.1 (trắc nghiệm)."}, {"id": "8.1", "kind": "checkpoint", "title": "Bài trả 8.1 — Thêm Bass thì làm gì với Melody?", "accepts": ["quiz"], "required": true, "quiz": {"mode": "single", "question": "Khi đã chọn xong nốt Bass cho một ô nhịp, bước tiếp theo đúng nhất là gì?", "options": [{"id": "a", "text": "Giữ nguyên cách xếp ngón Melody, không cần xem lại."}, {"id": "b", "text": "Bỏ Melody ở ô đó, chỉ giữ Bass."}, {"id": "c", "text": "Tính lại cách xếp ngón để tay trái vừa chơi được Melody vừa chơi được Bass, sửa nếu cần."}, {"id": "d", "text": "Thêm ngay nốt đệm Chord rồi mới thử đàn."}], "hint": "Xếp ngón không phải công đoạn riêng: thêm Bass là phải kiểm tra lại Melody."}}, {"kind": "note", "title": "Nhịp 2 · Đề bài tốt nghiệp", "text": "Đề bài: tự chuyển soạn bản nhạc phôi Thành Phố Buồn thành Solo Guitar trình độ 1. Bạn không học thuộc một bản mẫu — bạn tự chọn phương án và giải thích được lựa chọn của mình. Tải tờ phôi bên dưới, in ra A4 và làm bằng bút chì để dễ sửa. Kết thúc nhịp: Bài trả 8.2 (trắc nghiệm)."}, {"kind": "study", "title": "Giai đoạn 1 — Chuyển soạn trên giấy", "blocks": [{"b": "download", "title": "Bản nhạc phôi – Thành Phố Buồn (PDF A4)", "note": "Tờ phôi có khuông, TAB và lời ca; chưa có Bass, hợp âm hay kỹ thuật. In ra và ghi thêm bằng bút chì.", "label": "Tải bản nhạc phôi", "href": "https://wojmdilyflffvdtpovmq.supabase.co/storage/v1/object/public/lessons/solo01/chang1/thanh-pho-buon_ban-nhac-phoi_v1.pdf"}, {"b": "h", "text": "Bước 1 — MELODY"}, {"b": "ul", "items": ["Đọc cao độ và trường độ từng ô.", "Xác định vị trí từng nốt trên cần đàn (vùng, dây, ngăn).", "Đánh dấu kỹ thuật dự kiến: ép ngón, Slide, rung, luyến…", "Chưa cần phức tạp: ưu tiên ĐÚNG và chơi được."]}, {"b": "h", "text": "Bước 2 — BASS + XẾP NGÓN"}, {"b": "ul", "items": ["Bản phôi chưa ghi hợp âm: dựa vào giai điệu từng ô, ghi tên hợp âm bạn chọn (các hợp âm quen thuộc trong giọng Am như Am, Dm, E, A7) lên đầu ô.", "Từ hợp âm, chọn nốt Bass và ghi vị trí (dây, ngăn) vào từng ô nhịp.", "Tính xếp ngón để chơi Melody và Bass cùng nhau; nếu vướng, quay lại sửa Melody.", "Có thể cân nhắc Bass lệch ở chỗ phù hợp, theo hướng dẫn của Thầy trên lớp."]}, {"b": "h", "text": "Bước 3 — CHORD + XẾP NGÓN"}, {"b": "ul", "items": ["Dựa trên khung Melody và Bass đã có, chọn nốt đệm thuộc hợp âm phù hợp.", "Ghi vị trí chèn: dây, ngăn, ngón tay.", "Bảo đảm cả ba bè chơi được cùng lúc.", "Đừng lạm dụng nốt đệm: rõ ràng và chơi được quan trọng hơn nhiều nốt."]}, {"b": "callout", "label": "LƯU Ý", "text": "Xếp ngón không phải công đoạn riêng. Mỗi lần thêm Bass hoặc Chord, hãy tính lại cách xếp ngón Melody nếu cần."}]}, {"kind": "score", "title": "Tờ phôi trông thế nào — Thành Phố Buồn ô 1–3", "subtitle": "Chỉ để xem dạng bản; không phải bài mẫu", "lead": "Đây là phần đầu của tờ phôi. Bass, hợp âm và kỹ thuật là phần bạn tự thêm; Thầy không cung cấp sẵn lời giải.", "tex": "\\ts 4 4\n\\lyrics 0 \"Thành phố nào _ Nhớ không em _ Nơi chúng mình tìm phút êm đềm Thành phố nào vừa đi đã mỏi _ _ Đường quanh co quyện gốc thông _ già _ Chiều đan tay nghe nắng chan _ hòa Nắng hôn nhẹ làm hồng môi em Mắt em buồn trong sương chiều anh thấy đẹp hơn Một sáng nhau Rồi từ đó _ vì cách xa _ duyên tình thêm nhạt nhòa Rồi từ đó _ trốn phong ba _ em làm dâu nhà người Âm thầm anh tiếc thương đời Đau buồn em khóc chia phôi Anh về gom góp kỷ niệm tìm vui Thành phố buồn _ lắm tơ vương _ cơn gió chiều lạnh buốt tâm hồn và con đường ngày xưa lá đổ _ _ Giờ không em sỏi đá u _ buồn _ Giờ không em hoang vắng phố _ phường Tiếng chuông chiều chầm chậm thê lương tiễn đưa người quên núi đồi quên cả tình yêu\"\n.\nr.8{tu 3} 2.3.8{tu 3} 0.1.8{tu 3} |\n\\ro 2.3.4 2.3{t}.8{tu 3} 0.1.8{tu 3} 3.2.8{tu 3} 1.2.4 1.2{t}.8{tu 3} 0.3.8{tu 3} 2.3.8{tu 3} |\n2.4.4 2.4.8{tu 3} 3.2.8{tu 3} 1.2.8{tu 3} 2.3.4 r.8{tu 3} 0.1.8{tu 3} 3.1.8{tu 3} |", "tempo": "Tempo: ♩ = 60", "guidance": ["Ô 1 là ô lấy đà (chưa đủ 4 phách).", "Dòng chữ dưới khuông là lời ca, giúp bạn nhận ra câu nhạc."]}, {"id": "8.2", "kind": "checkpoint", "title": "Bài trả 8.2 — Chuẩn tốt nghiệp", "accepts": ["quiz"], "required": true, "quiz": {"mode": "single", "question": "Theo đề tốt nghiệp Chặng 1, điều kiện để đạt chuẩn tốt nghiệp trình độ 1 là gì?", "options": [{"id": "a", "text": "Đạt mức ĐÚNG ở cả ba bè: Melody, Bass, Chord."}, {"id": "b", "text": "Dùng thật nhiều kỹ thuật trong bản chuyển soạn."}, {"id": "c", "text": "Chỉ cần Melody đúng, Bass và Chord để sau."}, {"id": "d", "text": "Phải đạt cả ĐÚNG, ĐẸP và ĐỘC ĐÁO ở cả ba bè."}], "hint": "ĐÚNG là chuẩn tốt nghiệp. ĐẸP và ĐỘC ĐÁO là mức phát triển cao hơn, không bắt buộc."}}, {"kind": "note", "title": "Nhịp 3 · Thực hành và hoàn thiện", "text": "Chuyển bản giấy lên đàn, rồi dùng chính bài đàn để kiểm tra bản giấy. Nếu thấy một chỗ không chơi được, sửa trên giấy rồi đàn lại — bản cuối phải thống nhất với bài đàn. Kết thúc nhịp: Bài trả 8.3 (bản giấy + video)."}, {"kind": "study", "title": "Giai đoạn 2 — Thực hành trên đàn và cách chấm", "blocks": [{"b": "ol", "items": ["Đàn Melody theo bản giấy, chậm và đều.", "Ghép Melody + Bass: mỗi lần chỉ thêm một ô hoặc một câu.", "Ghép Melody + Bass + Chord: bỏ nốt đệm nào làm Melody hoặc Bass bị yếu.", "Sửa bản giấy cho đúng với những gì bạn đàn được, rồi quay video."]}, {"b": "h", "text": "Hệ thống chấm 3Đ"}, {"b": "table", "rows": [["Bè", "ĐÚNG — chuẩn tốt nghiệp", "ĐẸP — chất lượng âm nhạc", "ĐỘC ĐÁO — sáng tạo"], ["Melody", "Đúng cao độ, trường độ, liền mạch.", "Dùng kỹ thuật để giai điệu mượt, tự nhiên, chân thực.", "Có lựa chọn hoặc xử lý riêng, hợp lý và chơi được."], ["Bass", "Đúng nốt, đúng vị trí, phối hợp được với Melody.", "Âm Bass ấm, rõ, cân đối; Bass lệch phù hợp.", "Có cách chọn Bass riêng, nói được vì sao."], ["Chord", "Đúng hòa âm, nốt đệm phù hợp, xếp ngón khả thi.", "Nốt đệm sạch, hòa với hai bè còn lại, xếp ngón thuận.", "Có cách chèn nốt đệm riêng, hợp lý về âm nhạc."]]}, {"b": "callout", "label": "NGUYÊN TẮC", "text": "Đạt ĐÚNG ở cả ba bè là đạt chuẩn tốt nghiệp Chặng 1. ĐẸP và ĐỘC ĐÁO là mức phát triển cao hơn, không bắt buộc, và không tính theo số lượng kỹ thuật. Thầy đối chiếu bản giấy với video cho từng bè."}]}, {"id": "8.3", "kind": "checkpoint", "title": "Bài trả 8.3 — Bài tốt nghiệp Chặng 1", "required": true, "accepts": ["video_link", "text"], "prompt": "Nộp hai phần. (1) Video: dán link video bạn đàn đoạn Solo do chính mình chuyển soạn (ba bè theo năng lực của bạn). (2) Bản giấy: chụp ảnh hoặc xuất PDF tờ phôi đã hoàn thiện (có Melody, Bass, hợp âm/nốt đệm, xếp ngón), tải lên nơi lưu trữ của bạn (Google Drive, iCloud, Google Photos…) ở chế độ ai có link đều xem được, rồi dán link vào ô chữ cùng vài dòng: ‘Tôi chọn cách chuyển soạn này vì…’. Bản giấy và video phải thống nhất với nhau."}, {"kind": "assignment", "title": "Bài tập", "items": [{"label": "Bài 1.", "text": "Làm Bước 1 trên giấy: đọc Melody, ghi vị trí và kỹ thuật dự kiến cho cả đoạn."}, {"label": "Bài 2.", "text": "Làm Bước 2: ghi hợp âm, nốt Bass và cách xếp ngón; đàn thử Melody + Bass."}, {"label": "Bài 3.", "text": "Làm Bước 3: chọn nốt đệm, ghép đủ ba bè; bỏ phần nào làm Melody hoặc Bass yếu."}, {"label": "Bài 4.", "text": "Đàn, quay video, sửa bản giấy cho khớp bài đàn, rồi nộp Bài trả 8.3."}], "message": "Không cần giống ai và không cần nhiều nốt. Cần đúng, chơi được, và bạn giải thích được lựa chọn của mình."}, {"kind": "checklist", "items": ["Tôi nói được thứ tự Melody → Bass → Chord.", "Tôi đã ghi Melody, Bass và nốt đệm lên tờ phôi.", "Tôi đã tính lại xếp ngón mỗi khi thêm bè.", "Tôi đàn được từng bước: Melody, rồi Melody + Bass, rồi ba bè.", "Bản giấy của tôi thống nhất với video.", "⭐ Tôi nói được vì sao mình chọn cách chuyển soạn này."]}, {"kind": "studentNotes", "title": "Tôi chọn cách chuyển soạn này vì…", "lines": 6}]$j$::jsonb, now());
